func RunStep(ctx context.Context, t Target, env Env, set Settings, id StageID, prior Results) Results {
	res := prior.clone()
	set = set.Normalized()
	all := stages()
	gateOf := gatesOf(all)

	for _, s := range all {
		if s.id != id {
			continue
		}
		runStage(ctx, s, gateOf, t, env, set, &res)
	}
	return res
}

